// Build Reply -- generated by n8n/sendtrack/build_workflow.py.
// Part 1, verbatim: n8n/sendtrack/code_reply_topics.js. Part 2: n8n/sendtrack/code_reply.js.

// ===========================================================================
// The questions a reply may not answer -- shared by Build Reply and Assemble
// Reply (Section 9, Workflow 7). build_workflow.py prepends this file to both
// nodes, so the topic one node detects in the prospect's message is the same
// topic the other checks the draft against; two copies would drift and the
// drift would be invisible.
// ===========================================================================
//
// WHAT A REPLY MAY SAY is exactly what a first touch may say: the confirmed
// `claims_library` lines, and the facts in the lead's own enrichment record.
// Migration 013 narrowed every claim to what the Nova Agent Kit code actually
// does (`capabilities`), so "what the claims support" and "what the code
// supports" are the same set by construction, and a sentence outside it is an
// invention whether or not it happens to be true.
//
// A prospect's first reply, though, is usually a QUESTION, and the questions
// that come back are mostly about things no claim covers: what it costs, what
// it plugs into, which languages it speaks, where the data lives, how long it
// takes. The first touch never raised any of them, so there is nothing to
// widen -- which is precisely why a model will answer them from nowhere.
//
// So the answer is not "tag it afterwards", it is "do not answer it": the topic
// is detected in THEIR text before the model is called, the model is told to
// say we will confirm it, and the draft is flagged to the operator, who knows
// the answer and can put it in with EDIT. The five topics are the operator's
// list (2026-10-09).
//
// The patterns are deliberately broad. A false positive costs one hedged
// sentence and one line in the review email; a false negative is a made-up
// price or a made-up integration sent to a prospect over the operator's name.
const OPEN_TOPICS = [
  {
    topic: 'pricing',
    label: 'what it costs',
    re: /\b(?:pric(?:e|es|ing)|cost|costs|costly|how much|fee|fees|budget|quote|quotation|licen[cs]\w*|subscription|per (?:month|year|seat|user)|monthly|annual(?:ly)?|retainer|discount|invoice|payment terms)\b/i,
  },
  {
    topic: 'integrations',
    label: 'what it connects to',
    re: /\b(?:integrat\w*|API|APIs|webhook\w*|CRM|salesforce|hubspot|zapier|SSO|single sign-?on|LDAP|CTMS|eTMV|eTMF|EDC|SharePoint|Teams|Slack|calendar|google workspace|office ?365|plug(?:s|ged)? into|connect(?:s|ed|ion|ions)? (?:to|with))\b/i,
  },
  {
    topic: 'languages',
    label: 'which languages it speaks',
    re: /\b(?:language|languages|multi-?lingual|translat\w*|english|turkish|spanish|arabic|german|french|portuguese|polish|romanian|hungarian|czech|hindi|urdu|mandarin|japanese)\b/i,
  },
  {
    topic: 'security',
    label: 'security, hosting and data protection',
    re: /\b(?:secur\w*|GDPR|KVKK|HIPAA|GxP|21 CFR|part 11|data protection|privacy|confidential\w*|NDA|DPA|encrypt\w*|anonymi[sz]\w*|pseudonymi[sz]\w*|hosted?|hosting|on-?prem\w*|server location|where (?:is|are) (?:the )?data|data (?:residency|centre|center|retention|storage)|SOC ?2|ISO ?27001|penetration test|audit trail|validat\w*)\b/i,
  },
  {
    topic: 'timelines',
    label: 'how long it takes and when it can start',
    re: /\b(?:timeline|time-?line|how long|lead ?time|turn ?around|go[- ]live|deadline|availabilit\w*|when (?:can|could|would|will)|start date|roll ?out|implementation (?:time|period)|SLA|uptime|support hours|response time|maintenance)\b/i,
  },
];

// A sentence that says we will come back with the answer, rather than giving
// one. Assemble Reply requires one of these for every topic the prospect
// raised: without it, a paragraph that mentions pricing is answering about
// pricing.
const DEFERRAL_RE = /\b(?:I(?:'| wi)?ll (?:confirm|check|find out|come back|get back|send you the detail)|let me (?:confirm|check|find out)|I (?:do not|don't) want to guess|rather than guess|confirm (?:that|this|these|the detail)|get back to you (?:on|with|about)|come back to you (?:on|with|about)|check (?:that|this) (?:and|then|with)|I will ask)\b/i;

// Which of the five the prospect actually raised, in the order above.
function topicsIn(text) {
  const t = String(text === null || text === undefined ? '' : text);
  return OPEN_TOPICS.filter(function (o) { return o.re.test(t); }).map(function (o) { return o.topic; });
}

function topicLabel(topic) {
  const hit = OPEN_TOPICS.filter(function (o) { return o.topic === topic; })[0];
  return hit ? hit.label : topic;
}

function topicRe(topic) {
  const hit = OPEN_TOPICS.filter(function (o) { return o.topic === topic; })[0];
  return hit ? hit.re : null;
}

function deferralIn(text) {
  return DEFERRAL_RE.test(String(text === null || text === undefined ? '' : text));
}

// Build Reply -- n8n Code node (Run Once for All Items).
//
// Section 9, Workflow 7. A prospect has answered a cold email; this builds the
// request that drafts our answer. Claude Reply writes it, Assemble Reply checks
// it against the first touch's own claim rules and frames it, and the operator
// approves it by email with a one-time code. NOTHING a model writes here
// reaches a prospect without that approval.
//
// FOUR SOURCES, AND NOTHING ELSE (the operator's rule, 2026-10-09):
//   1. what they wrote -- the text above the quoted thread, as Classify Inbound
//      cut it;
//   2. the thread -- our first touch exactly as it was sent, and any follow-up
//      that went out;
//   3. the lead's enrichment record, worded with the same boundary sentences
//      Workflow 4's fact sheet uses, so a fact cannot be joined to another one;
//   4. the confirmed claims_library lines (migration 013 narrowed each to what
//      the Nova Agent Kit code does), plus how we found them -- leads.source.
//
// A question none of those four can answer is not answered. The five topics
// that come back in practice -- pricing, integrations, languages, security,
// timelines -- are detected in THEIR text before the call (code_reply_topics.js,
// prepended to this node), the model is told to say we will confirm them, and
// the draft carries the flag so the review email can put the question in front
// of the operator, who knows the answer.
//
// A reply is never auto-approved and never claim-checked: the operator reads
// every one. That is why there is no Approval Gate in this workflow and why
// migration 018 refuses an `approved_by = 'auto'` reply on the table as well.

// Section 5 / Section 9, substituted at build time.
const REPLY_SYSTEM_PROMPT = "You write one short email replying to a small contract research organisation (CRO) that has\nanswered a cold email from Abdullah Amir. Abdullah Amir reads your draft and approves,\nedits or rejects it before anything is sent. You are answering a real person who took the time\nto write back.\n\nEVERY MESSAGE GIVES YOU FOUR SOURCES, and they are the only ones you have:\n1. THEIR MESSAGE -- what they wrote above the quoted thread.\n2. THE THREAD -- our own earlier messages, exactly as they were sent.\n3. THEIR RECORD -- the facts we hold about their company, each with a sentence saying what it\n   does not mean. Read those boundaries: two true facts joined into one sentence is the\n   commonest way these drafts go wrong.\n4. APPROVED CLAIMS -- the only things you may say about what we built, the problem it solves\n   and who uses it. You may rephrase a line. You may never widen what it means.\n\nANYTHING ELSE YOU DO NOT ANSWER. Not vaguely, not approximately, not \"typically\". The\nmessage lists the questions they asked that none of the four sources settles -- about pricing, integrations, languages, security or timelines -- and for each one you say, in a\nnormal sentence, that you will confirm it and come back. Give no hint of the answer: not a\nrange, not \"it depends\", not \"usually\". Name every one of them in `deferred` and say in\n`flag` what has to be confirmed. Abdullah Amir knows those answers and will put them in.\nA guessed price, integration, language, hosting detail or date is the one failure that cannot\nbe taken back, because it reaches a prospect over a real person's name.\n\nANSWER WHAT THEY ACTUALLY SAID, in their own order, and nothing they did not raise:\n- If they declined, accept it in one line, leave one door open, and stop. Never argue, never\n  re-pitch, never ask them to reconsider, never suggest they have misunderstood.\n- If they asked something the record or the thread answers, answer it plainly and briefly.\n- If they asked how we found them, the record says; say exactly that and no more.\n- If they asked for something we have (the one approved link), offer it once.\nThen exactly ONE next step, from the approved list, sized to what they wrote: a declining\nreply gets the lightest one, an interested reply the direct one.\n\nTHE PROSPECT: only the facts in their record and in the thread. Never describe them as\nsponsoring anything -- in these emails \"sponsor\" means the biotech, pharma, device or\nacademic company that hires a CRO, their client. Never invent a trial, a person, a city or a\nnumber. Do not name their company back at them.\n\nTHE PRODUCT: the first email introduced it; refer back to it (\"the assistant\"). Never call it\na chatbot or a Q&A bot. The word \"AI\" at most once. Never \"AI-powered\". Name it only as\n\"(we call it Nova)\", at most once, and only if naming it helps.\n\nNO REPEATS: the lines you use must not repeat the same capability -- each one says what it is\nabout -- and do not restate a capability the thread already covered.\n\nCLAIMS -- forbidden, all of them:\n- guarantees (\"you'll never lose a sponsor\")\n- any number, percentage or multiplier that is not in the approved claims, their record or\n  the thread\n- claiming to identify anonymous website visitors\n- naming any CRM, tool or integration\n- supported languages\n- any count of clients beyond the deployments the proof line names, and never the phrase\n  \"two CROs\"\n- saying it books calls or fills a calendar -- it sends the sponsor your booking link, and the\n  sponsor books\n- saying it answers from SOPs or from documents -- it answers from their website\nA stakes line is about the industry, not about us.\n\nTHE NEXT STEP: one question, from the list, rephrased to fit what they said. No scheduling\nlink, no call length, no second question. The body before it asks for nothing.\n\nEVERYWHERE: plain text. No bullets, no headings, no placeholders, no merge tags. At most one\nlink, and only the one offered. No greeting, no sign-off and no opt-out line -- all three are\nadded afterwards. Never these words: revolutionary, cutting-edge, innovative, game-changing, seamless. No invented urgency, no\nflattery, no exclamation marks, and never thank them twice.\n\nReturn JSON: body (everything before the next step, paragraphs separated by a blank line);\nask (the one next step); claims (the code of every approved line the reply used, the next step\nincluded); deferred (the topic names you did not answer); flag (one line saying what Abdullah Amir has to confirm, or \"\" if nothing).";
const CLAUDE_REQUEST = {"model": "claude-sonnet-5-5", "max_tokens": 16000, "output_config": {"effort": "high", "format": {"type": "json_schema", "schema": {"type": "object", "properties": {"body": {"type": "string"}, "ask": {"type": "string"}, "claims": {"type": "array", "items": {"type": "string"}}, "deferred": {"type": "array", "items": {"type": "string"}}, "flag": {"type": "string"}}, "required": ["body", "ask", "claims", "deferred", "flag"], "additionalProperties": false}}}};
const CACHE_CONTROL = { type: 'ephemeral' };
const SENDER_NAME = "Abdullah Amir";
const THERAPEUTIC_AREAS = ["Oncology", "Cardiovascular", "Central Nervous System", "Immunology", "Infectious Disease", "Endocrinology", "Metabolic Disorders", "Respiratory", "Rare Diseases", "Internal Medicine", "Anesthesiology", "Dermatology", "Rheumatology", "Ophthalmology", "Gastroenterology", "Nephrology", "Hematology", "Other"];

// A reply is an answer, not a pitch: long enough to answer what they asked and
// name one next step, short enough to read on a phone. Assemble Reply tags
// anything outside this.
const REPLY_MIN_WORDS = 40;
const REPLY_MAX_WORDS = 120;

// Operator instruction, 2026-10-09: a reply never reuses the "two CROs" proof
// line, and never calls Vertex Clinical Research a CRO -- it is a clinical
// research centre. The rule is written against the TEXT of a claims_library
// line rather than against a code, because the table is the library and a
// reworded row must not escape it. A lead whose country the library can only
// serve with that line is simply offered no proof, and the reply makes no proof
// claim: a missing claim is not a defect in an answer to a question.
const REPLY_PROOF_REFUSED = [/\btwo CROs?\b/i, /\bVertex\b[^.]{0,40}\bCRO\b/i];

function rStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function rFold(v) {
  return rStr(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

function rWords(v) {
  const t = rStr(v);
  return t ? t.split(/\s+/).length : 0;
}

// --- the claims this reply may draw on ---------------------------------------

function replyLibrary(raw) {
  const out = [];
  for (const row of Array.isArray(raw) ? raw : []) {
    if (!row || typeof row !== 'object') continue;
    out.push({
      code: rStr(row.code),
      slot: rStr(row.slot),
      body: rStr(row.body),
      countries: Array.isArray(row.countries) && row.countries.length ? row.countries.map(rFold) : null,
      measured: row.measured === true,
      confirmed: row.confirmed === true,
      active: row.active === true,
      capabilities: Array.isArray(row.capabilities) ? row.capabilities.map(rStr).filter(Boolean) : [],
    });
  }
  return out;
}

// The proof for this lead's country, resolved exactly as Assess Grounding and
// Build Follow-Up resolve it (a measured line wins; a row with no countries
// serves everyone else) -- and then the refused wordings are dropped.
function replyProof(rows, country) {
  const key = rFold(country);
  const serving = rows.filter(function (x) { return x.countries && x.countries.indexOf(key) !== -1; });
  const pick = serving.length ? serving : rows.filter(function (x) { return !x.countries; });
  const measured = pick.filter(function (x) { return x.measured; });
  const chosen = measured.length ? measured : pick;
  return chosen.filter(function (x) {
    return !REPLY_PROOF_REFUSED.some(function (re) { return re.test(x.body); });
  });
}

function replyLines(rows) {
  return rows.map(function (x) {
    return { code: x.code, body: x.body, confirmed: x.confirmed, capabilities: x.capabilities };
  });
}

// Everything a reply may say about the product, and the one link it may carry.
// Only active lines with text: an empty or retired row offers nothing.
function replyPools(r) {
  const lib = replyLibrary(r.library).filter(function (l) { return l.active && l.body; });
  const bySlot = function (slot) { return lib.filter(function (l) { return l.slot === slot; }); };
  return {
    description: replyLines(bySlot('description')),
    angle: replyLines(bySlot('angle')),
    benefit: replyLines(bySlot('benefit')),
    proof: replyLines(replyProof(bySlot('proof'), r.country)),
    ask: replyLines(bySlot('ask')),
    // Section 9, Workflow 4's link policy: the only URL allowed anywhere is the
    // library's own `link` line, and it is offered only while it is active AND
    // confirmed and actually holds a URL. L-NP is empty and inactive today, so
    // a reply carries no link at all and Assemble Reply tags any URL in one.
    link: replyLines(bySlot('link').filter(function (l) {
      return l.confirmed && /\bhttps?:\/\/\S+/i.test(l.body);
    })),
  };
}

// --- the prospect, as a fact sheet with boundaries ---------------------------
//
// Workflow 4's wording, for Workflow 4's reason: a sentence can use no invented
// word and still assert an untrue RELATIONSHIP between two true facts, so each
// fact carries the sentence that says what it does not mean.
function replyRecord(r) {
  const facts = [];
  const areas = Array.isArray(r.therapeutic_areas) ? r.therapeutic_areas.map(rStr).filter(Boolean) : [];
  if (areas.length) {
    facts.push('Therapeutic areas listed on their own website: ' + areas.join(', ') +
      '. This says nothing about which area any particular trial belongs to.');
  }
  const phases = Array.isArray(r.phases) ? r.phases.map(rStr).filter(Boolean) : [];
  if (phases.length) facts.push('Trial phases listed on their own website: ' + phases.join(', ') + '.');
  if (rStr(r.city)) {
    facts.push('The company is based in ' + rStr(r.city) +
      '. This says nothing about where any trial runs or where any staff sit.');
  }
  if (rStr(r.founder_name)) {
    facts.push('Named on their own site as founder or MD: ' + rStr(r.founder_name) +
      '. This says nothing about which trials or clients this person personally handles.');
  }
  const n = Number(r.employee_estimate);
  if (r.employee_estimate !== null && r.employee_estimate !== undefined && Number.isInteger(n) && n > 0) {
    facts.push('Their own site states a team of ' + n + ' people. This says nothing about what they do.');
  }
  if (rStr(r.source)) {
    facts.push('How we found them, and the only answer to "where did you hear about us": ' + rStr(r.source) +
      '. Nothing else about how they came to our attention is on record.');
  }
  facts.push('No trial is part of this record. The first email may name one; nothing here confirms it.');
  return ['Company: ' + rStr(r.company_name), 'Country: ' + rStr(r.country)]
    .concat(facts.map(function (f, i) { return String(i + 1) + '. ' + f; })).join('\n');
}

// Our side of the thread, as they read it: the first touch and any follow-up,
// oldest first, without their signatures and quoted tails.
function threadText(r) {
  const out = [];
  for (const m of Array.isArray(r.thread) ? r.thread : []) {
    if (!m || !rStr(m.body)) continue;
    const when = new Date(m.sent_at);
    out.push('--- ' + (isNaN(when.getTime()) ? 'earlier' : when.toUTCString().slice(0, 16)) +
      ', we wrote (subject "' + rStr(m.subject) + '"):');
    out.push(rStr(m.body));
  }
  return out.join('\n');
}

function sheet(heading, list, withCaps) {
  if (!list.length) return heading + '\n  (none)';
  return [heading].concat(list.map(function (l) {
    return '  [' + l.code + '] ' + l.body +
      (withCaps && l.capabilities.length ? '  (about: ' + l.capabilities.join(', ') + ')' : '');
  })).join('\n');
}

function replyRequest(r, item) {
  const theirs = rStr(r.reply_text);
  if (!theirs) return null;          // nothing to answer; nothing is written
  const pools = replyPools(r);
  if (!pools.ask.length) return null; // the library cannot complete a reply

  const record = replyRecord(r);
  const thread = threadText(r);
  const open = topicsIn(theirs);
  const deferrals = open.map(function (t) { return '  - ' + t + ': ' + topicLabel(t); }).join('\n');

  const prompt = [
    'THEIR MESSAGE, which arrived ' + rStr(r.received_at) + ' from ' + rStr(r.from_addr) +
      ' with the subject "' + rStr(r.subject) + '". This is what you are answering:',
    '---',
    theirs,
    '---',
    '',
    'THE THREAD SO FAR -- our own messages, exactly as they were sent:',
    thread || '  (nothing on record)',
    '',
    'THEIR RECORD. Every fact you may state about them, and only what it says:',
    record,
    '',
    'APPROVED CLAIMS. Everything you may say about what we built, the problem it solves and who',
    'uses it comes from these lines. Rephrase freely; never widen what a line says.',
    '',
    sheet('WHAT IT IS:', pools.description, true),
    '',
    sheet('PAIN AND STAKES:', pools.angle, false),
    '',
    sheet('WHAT IT DOES:', pools.benefit, true),
    '',
    sheet('PROOF -- only if you name a deployment; it is matched to their country:', pools.proof, false),
    '',
    sheet('THE ONE LINK you may include, at most once, and only if it genuinely helps:', pools.link, false),
    '',
    sheet('NEXT STEP -- end with ONE of these, rephrased to fit what they said:', pools.ask, false),
    '',
  ].concat(open.length ? [
    'QUESTIONS YOU MAY NOT ANSWER. They raised these, and nothing above settles any of them:',
    deferrals,
    'For each one, say in a few words that you will confirm it and come back -- a real sentence,',
    'not a brush-off, and no hint of what the answer might be. Name every one of them in',
    '`deferred`, and say in `flag` what the operator has to confirm. Never guess a price, a',
    'product it connects to, a language, anything about hosting or data, or a date.',
    '',
  ] : []).concat([
    'WRITE THE REPLY. Answer what they actually said, in their order, from the sources above.',
    'If they declined, accept it in one line and leave one door open -- never push back.',
    'If they asked something the record answers, answer it plainly.',
    'Then exactly ONE next step, from the list above, sized to what they wrote.',
    'The body plus the next step is ' + REPLY_MIN_WORDS + '-' + REPLY_MAX_WORDS + ' words.',
    'Write no greeting, no sign-off and no opt-out line: all three are added afterwards.',
    'In `claims`, list the code of every approved line the reply used, the next step included.',
  ]).join('\n');

  // Every taxonomy area nothing in front of the model names: the reply may not
  // name one either (Assemble Reply tags it `ungrounded-area`).
  const corpus = [theirs, thread, record].concat(
    ['description', 'angle', 'benefit', 'proof', 'ask', 'link'].map(function (s) {
      return pools[s].map(function (l) { return l.body; }).join('\n');
    })).join('\n');
  const plain = ' ' + rFold(corpus).replace(/[^a-z0-9]+/g, ' ') + ' ';
  const absent = THERAPEUTIC_AREAS.filter(function (a) {
    return a !== 'Other' && plain.indexOf(' ' + rFold(a).replace(/[^a-z0-9]+/g, ' ') + ' ') === -1;
  });

  return {
    json: {
      lead_id: r.lead_id,
      inbound_message_id: r.inbound_message_id,
      country: r.country,
      company_name: r.company_name,
      domain: r.domain,
      from_addr: r.from_addr,
      their_subject: r.subject,
      their_text: theirs,
      received_at: r.received_at,
      // The subject threads the conversation: theirs with one 'Re:' on it.
      subject: 'Re: ' + rStr(r.subject).replace(/^(?:(?:re|fwd|fw|aw|sv|vs)\s*:\s*)+/i, ''),
      greeting: rStr(r.their_name) ? 'Hello ' + rStr(r.their_name) + ',' : 'Hello,',
      // The From display name is not stored, so the quoted header names the
      // address that wrote. A name is used only in the greeting, and only when
      // it is the contact on file (their_name) -- a first name guessed out of a
      // local part would be an invented fact in the first line of the reply.
      quote_attribution: rStr(r.their_name) ? rStr(r.their_name) + ' <' + rStr(r.from_addr) + '>'
        : rStr(r.from_addr),
      library_pools: pools,
      open_topics: open,
      absent_areas: absent,
      corpus: corpus,
      sender_name: SENDER_NAME,
      prompt: prompt,
      // Prompt caching (Section 3, on since 2026-10-08). The cached block is
      // exactly the system prompt: build-substituted, so byte-identical for
      // every reply and every run, and comfortably over Sonnet 5.5's 512-token
      // minimum. Everything about this prospect is in the user message after
      // it, where a cache entry would be read by nothing. The 5-minute TTL and
      // why a run's own calls cannot read each other's write are recorded in
      // drafting's code_assess.js.
      request: Object.assign({}, CLAUDE_REQUEST, {
        system: [{ type: 'text', text: REPLY_SYSTEM_PROMPT, cache_control: CACHE_CONTROL }],
        messages: [{ role: 'user', content: prompt }],
      }),
    },
    pairedItem: { item: item },
  };
}

// ---------------------------------------------------------------------------
// Node body (Run Once for All Items)
// ---------------------------------------------------------------------------
//
// An empty queue can arrive as one { success: true } item: the Postgres node
// emits that placeholder when it does not classify a statement as a SELECT, and
// a WITH ... SELECT is exactly the shape its parser has to guess at. Keeping
// only rows that carry a lead_id turns that into zero items, so nothing
// downstream runs -- and no paid call is made.
const out = [];
$input.all().forEach(function (it, i) {
  if (!it.json || it.json.lead_id === undefined || it.json.lead_id === null) return;
  const built = replyRequest(it.json, i);
  if (built) out.push(built);
});
return out;

// Assemble Reply -- generated by n8n/sendtrack/build_workflow.py.
// Part 1, verbatim: n8n/drafting/code_assemble.js above its 'Node body' marker -- the
// first touch's claim rules. Part 2, verbatim: n8n/sendtrack/code_reply_topics.js.
// Part 3: n8n/sendtrack/code_reply_assemble.js.

// Assemble Drafts -- n8n Code node (Run Once for Each Item).
//
// Turns one Claude response into the two draft rows Section 9 asks for ("email
// variant + LinkedIn variant per lead into `drafts`"), and enforces every rule
// of NovaScout_DraftingSkill.md v3, section 3, that a string match can enforce.
//
// Skill v3 moved from verbatim line-picking to composition: Claude Sonnet 5.5
// writes the whole email -- subject, body and one ask -- from one prospect fact
// plus the approved claims Assess Grounding handed it. That makes this node the
// only thing standing between the model's prose and the review queue, so every
// rule the skill states as a rule is checked here, deterministically (build
// rule 3), on what actually came back:
//
//   length        body 70-110 words is the target; above 125 is tagged `long`
//   ask           exactly one: one question in the ask, no request in the body
//   links         none in warm-up weeks 1-2, then only the library's link line
//   product name  at most once, in brackets, never in the subject
//   "AI"          at most once, never in the subject, never "AI-powered"
//   sponsor       the prospect is never the one sponsoring ("You're sponsoring")
//   claims        no guarantee, no number the library and facts do not hold, no
//                 visitor identification, no named CRM or tool, no languages,
//                 never "chatbot", never that Nova books a call, never SOPs or
//                 client documents as its source; no two claim lines that
//                 repeat a capability
//   proof         the geography-matched deployment is named; no other one is
//   grounding     no therapeutic area the lead lacks; no founder or city opener;
//                 a trial is never credited to their website
//
// The opt-out sentence, the signature and the greeting are appended HERE, not
// generated. Section 5 locks the opt-out verbatim and makes it the whole basis
// for GDPR/KVKK legitimate interest.
//
// A violation tags the draft's `variant` rather than discarding it. The reviewer
// sees the tag next to the text; a silently dropped draft teaches nobody
// anything. Every draft still needs a human approval before Workflow 6 sends it.

// ---------------------------------------------------------------------------
// Locked constants. build_workflow.py parses each out of NovaScout_MasterRef.md
// or NovaScout_DraftingSkill.md and refuses to build on drift.
// ---------------------------------------------------------------------------

// Section 5, "Message rules -- LOCKED". Verbatim, including the straight
// apostrophes -- this string is the opt-out mechanism, not a paraphrase of it.
const OPT_OUT = "If this isn't relevant, reply 'no' and I won't follow up.";

// Skill v3 section 3, Length: "The body (everything above the opt-out line)
// should be 70-110 words and never more than 125." Counted over the body and
// the ask -- the greeting is the fixed frame, as in v2. Only the ceiling tags;
// "shorter is fine if nothing useful is lost".
const BODY_TARGET_MIN = 70;
const BODY_TARGET_MAX = 110;
const BODY_CEILING = 125;

// Section 5: "Maximum one plain URL. No buttons."
const MAX_URLS = 1;

// Master Ref Section 9, Workflow 4, Links: none in warm-up weeks 1-2. From week
// 3 the one URL Section 5 allows may appear -- and only the library's link
// line, appended here, never written by the model.
const LINK_FREE_WEEKS = 2;

// Skill v3 section 3, Subject: "30-55 characters ... Never the product name.
// Never 'AI'. No 'Re:', no 'Fwd:', no capitals."
const SUBJECT_MIN_CHARS = 30;
const SUBJECT_MAX_CHARS = 55;
const SUBJECT_REPLY_PREFIXES = ['re', 'fwd'];

// Skill v3 section 3, Naming the product: "The name appears at most once, in
// brackets". "The word 'AI' appears at most once".
const PRODUCT_NAME = 'Nova';
const PRODUCT_NAME_MAX = 1;
const AI_MAX = 1;

// Skill v3 section 3, Everywhere: "No banned adjectives (revolutionary,
// cutting-edge, innovative, game-changing, seamless)." The rest are the same
// register and fail the same way.
const BANNED_ADJECTIVES = [
  'revolutionary',
  'cutting-edge',
  'cutting edge',
  'innovative',
  'game-changing',
  'game changing',
  'seamless',
  'best-in-class',
  'world-class',
  'state-of-the-art',
  'leverage',
  'synergy',
  'unlock',
  'supercharge',
];

// The live deployments a proof line can name. Which of them this lead may hear
// about is decided by its proof pool (Assess Grounding, by country).
const DEPLOYMENTS = ['NoblePath', 'Vertex'];

// Skill v3 section 3, Claims, forbidden: "naming a specific CRM, tool or
// integration". Generic words ("your CRM", "a spreadsheet") are fine. Only
// names that are not also ordinary English words are listed, so a false
// positive costs a review tag, not a wrong one.
const NAMED_TOOLS = [
  'hubspot', 'salesforce', 'pipedrive', 'zoho', 'microsoft dynamics', 'dynamics 365', 'monday.com',
  'freshsales', 'freshworks', 'zendesk', 'google sheets', 'google sheet', 'airtable', 'slack',
  'microsoft teams', 'calendly', 'gmail', 'whatsapp', 'veeva', 'intercom', 'resend', 'mailchimp',
];

// Section 9, Workflow 4: "no merge-tag phrasing tells". The literal tags a
// template would leave behind ([First Name], {{company}}, <domain>).
const MERGE_TAG = /(\{\{[^}]*\}\})|(\[[A-Za-z][A-Za-z _-]{1,30}\])|(<[A-Za-z][A-Za-z _-]{1,30}>)/;

const URL_RE = /\b(?:https?:\/\/|www\.)[^\s<>()]+/gi;

// Skill v3 section 3, Hook: "Never describe the prospect as sponsoring anything
// ('You're sponsoring...' is banned)." Every way the v2 drafts and fact sheet
// put it.
const PROSPECT_SPONSOR = [
  /\byou(?:['’]re| are)\s+(?:also\s+|currently\s+|now\s+|actively\s+)?sponsor(?:ing|s)?\b/i,
  /\byou(?:['’]re| are)\s+(?:the|a|an)\s+(?:\w+\s+)?sponsor\b/i,
  /\byou\s+sponsor(?:ed|s)?\b/i,
  /\byou as (?:the |a )?sponsor\b/i,
  /\bsponsored by you\b/i,
  /\byour (?:own )?(?:sponsored|sponsorship)\b/i,
];

// Skill v3 section 3, Claims, forbidden. Each is a pattern for one rule.
const GUARANTEE = /\bguarantee\w*|\bnever (?:again )?(?:lose|miss)\b|\bno (?:lead|inquiry|inquiries|sponsor|sponsors) (?:is |are |gets |get |will be )?(?:ever )?(?:lost|missed)\b|\b100 ?%|\bwill (?:win|double|triple|increase|grow|boost)\b|\byou(?:['’]ll| will) (?:never|always|win|get more)\b|\b(?:ensures?|makes? sure) (?:you|that you) never\b/i;
const VISITOR_ID = /\b(?:identif\w*|reveal\w*|unmask\w*|de-?anonymi\w*|track\w*)\b[^.?!]{0,60}\b(?:visit\w*|visitors?|anonymous|traffic|browse\w*)\b|\banonymous (?:visitors?|traffic)\b|\b(?:see|know|tells? you|shows? you)\s+(?:exactly\s+)?(?:who|which \w+)\s+(?:visit\w*|browse\w*|land\w* on|came to)\b/i;
const LANGUAGES = /\bmulti-?lingual\b|\blanguages?\b|\b(?:turkish|spanish|arabic|german|french|portuguese|english|polish|romanian|hungarian|czech|hindi|urdu)\b/i;
const CHATBOT = /\bchat ?bots?\b|\bQ ?& ?A bots?\b/i;
const AI_POWERED = /\bAI[- ]?(?:powered|driven|based)\b/i;
// Settled 2026-10-02 against the Nova Agent Kit code (migration 013): Nova does
// not book -- it sends the booking link and the sponsor books through it -- and
// it answers from the CRO's website, never from SOPs or documents a client
// provides. "So they can book a call" is fine; Nova "books the call" is not.
const NOVA_BOOKS = /\bbooks\s+(?:the\s+|a\s+|qualified\s+|sponsor\s+)?(?:calls?|meetings?|demos?)\b|\b(?:into|onto|straight into)\s+your\s+(?:calendar|diary)\b|\bschedules\s+(?:the\s+|a\s+)?(?:calls?|meetings?)\b/i;
const SOP_SOURCE = /\bSOPs?\b|\bstandard operating procedures?\b|\b(?:your|their)\s+(?:own\s+)?(?:documents|documentation)\b/i;

// Skill v3 section 3, Claims: "any number, percentage or multiplier that is not
// in section 4". Digit tokens are checked against the library and the facts;
// these are the spelled-out numbers and multipliers a model reaches for. "one"
// is not here -- "one word back", "one question" are the skill's own words.
const NUMBER_WORDS = [
  'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'twenty',
  'thirty', 'fifty', 'hundred', 'hundreds', 'thousand', 'thousands', 'million', 'millions', 'billion',
  'dozen', 'dozens', 'double', 'doubles', 'doubled', 'triple', 'triples', 'tripled', 'twice', 'half',
  'percent', 'tenfold',
];
// A digit in the corpus licenses its word: the fact sheet says "2 recruiting
// trials", the model may write "two recruiting trials".
const DIGIT_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
  'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty'];

// Skill v3 section 3, Ask: "Exactly one ask. The reply costs one word. No
// links, no scheduling link, no '30-minute call'." The ask is its own field in
// the model's schema, so exactly one ask means: one question there, and no
// request anywhere in the body.
const REQUEST_IN_BODY = /\b(?:would you|could you|are you open|worth a (?:look|chat|call|try|conversation)|let me know|reply (?:yes|no|with|to)|one word back|shall i|should i|want me to|happy to (?:set|send|show|share|walk)|interested in (?:a|seeing|trying|hearing)|open to a|up for a|free for a)\b/i;
const ASK_SCHEDULING = /\b\d+[- ]?min(?:ute)?s?\b|\b(?:fifteen|twenty|thirty)[- ]minutes?\b|\bcalendly\b|\bschedul\w*|\bbook (?:a |some )?(?:time|slot|call|meeting)\b|\b(?:time|slot)s? (?:that )?works?\b/i;

// Skill v3 section 3, Hook: "Never open on the founder's name or the city."
// And the trial fact is on ClinicalTrials.gov, not on their site.
const HOOK_SOURCE_OPENING = /^\s*(clinicaltrials\.gov|according to)\b/i;
const SITE_CLAIM = /\b(your|their|the)\s+(web\s?)?site\b/i;
const TRIAL_WORD = /\b(trials?|stud(y|ies))\b/i;

// Acronyms a subject may carry in capitals.
const SUBJECT_ACRONYMS = ['CRO', 'CROS', 'BD'];

// The order claim codes are recorded in `variant`.
const SLOT_ORDER = ['description', 'angle', 'benefit', 'proof', 'ask', 'link'];

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

// A word is a token with a letter or a digit in it. A dash between clauses is
// punctuation, not a word.
function words(v) {
  const t = str(v);
  return t ? t.split(/\s+/).filter(function (w) { return /[\p{L}\p{N}]/u.test(w); }).length : 0;
}

function fold(v) {
  return str(v).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
}

// A model that ignores "no greeting, no sign-off" produces a duplicate greeting
// once we prepend our own, and a sign-off that collides with the signature.
// Both are deterministic to strip.
const SIGNOFFS = [
  'best regards', 'kind regards', 'warm regards', 'best wishes', 'regards',
  'best', 'thanks', 'thank you', 'cheers', 'sincerely', 'yours sincerely',
];

function stripGreeting(body, greeting) {
  let out = str(body);
  const g = str(greeting).replace(/[,\s]+$/, '');
  // The trailing comma or colon is REQUIRED: optional, this ate the start of any
  // body that merely began with "Hi" or "Hello".
  out = out.replace(/^\s*(hi|hello|hey|dear|greetings)\b[^\n,]{0,40}[,:]\s*\n?/i, '');
  if (g && out.toLowerCase().indexOf(g.toLowerCase()) === 0) {
    out = out.slice(g.length).replace(/^[,\s]+/, '');
  }
  return out.trim();
}

function stripSignoff(body) {
  const lines = str(body).split('\n');
  while (lines.length) {
    const last = lines[lines.length - 1].trim().toLowerCase().replace(/[,.!]+$/, '');
    if (!last) { lines.pop(); continue; }
    if (SIGNOFFS.indexOf(last) !== -1 || (lines.length > 1 && /^[a-z]{2,20}$/.test(last))) {
      lines.pop();
      continue;
    }
    break;
  }
  return lines.join('\n').trim();
}

// Paragraphs as the model wrote them, blank-line separated, inner whitespace
// tidied; never more than one blank line in a row.
function cleanText(raw, greeting) {
  return stripSignoff(stripGreeting(raw, greeting))
    .split(/\n\s*\n/)
    .map(function (p) { return p.replace(/\s*\n\s*/g, ' ').trim(); })
    .filter(Boolean)
    .join('\n\n');
}

function urlsIn(v) {
  return str(v).match(URL_RE) || [];
}

function bannedAdjectivesIn(v) {
  const t = ' ' + str(v).toLowerCase() + ' ';
  return BANNED_ADJECTIVES.filter(function (a) { return t.indexOf(a) !== -1; });
}

// Trial titles are quoted from ClinicalTrials.gov and can hold anything -- a
// digit, a question mark, a therapeutic area. The checks judge what the model
// wrote around a title, not the title it was given.
function withoutTitles(text, titles) {
  let out = str(text);
  for (const t of titles || []) {
    const title = str(t);
    if (!title) continue;
    let at = out.toLowerCase().indexOf(title.toLowerCase());
    while (at !== -1) {
      out = out.slice(0, at) + ' ' + out.slice(at + title.length);
      at = out.toLowerCase().indexOf(title.toLowerCase());
    }
  }
  return out;
}

function digitTokens(v) {
  return (str(v).match(/[\p{L}\p{N}]*\p{N}[\p{L}\p{N}]*/gu) || []).map(function (t) { return t.toLowerCase(); });
}

// Numbers the text states that the corpus (this lead's facts plus every claim it
// was offered) does not: a digit token, a spelled-out number or multiplier, or a
// percent sign.
function unlicensedNumbers(text, corpus) {
  const haveDigits = {};
  digitTokens(corpus).forEach(function (t) { haveDigits[t] = true; });
  const bad = digitTokens(text).filter(function (t) { return !haveDigits[t]; });
  let corpusWords = ' ' + fold(corpus).replace(/[^a-z0-9]+/g, ' ') + ' ';
  Object.keys(haveDigits).forEach(function (t) {
    if (/^\d+$/.test(t) && Number(t) < DIGIT_WORDS.length) corpusWords += DIGIT_WORDS[Number(t)] + ' ';
  });
  const textWords = fold(text).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean);
  textWords.forEach(function (w) {
    if (NUMBER_WORDS.indexOf(w) !== -1 && corpusWords.indexOf(' ' + w + ' ') === -1) bad.push(w);
  });
  if (str(text).indexOf('%') !== -1 && str(corpus).indexOf('%') === -1) bad.push('%');
  return bad;
}

function absentAreasNamed(text, absentAreas) {
  const plain = ' ' + fold(text).replace(/[^a-z0-9]+/g, ' ') + ' ';
  return (absentAreas || []).filter(function (a) {
    return plain.indexOf(' ' + fold(a).replace(/[^a-z0-9]+/g, ' ') + ' ') !== -1;
  });
}

// Does the text open on this name (or its first word)? Plain string compare.
function startsWithName(text, name) {
  const t = fold(text);
  const n = fold(name);
  if (!n) return false;
  const first = n.split(/\s+/)[0];
  const opensOn = function (w) {
    return t.indexOf(w) === 0 && (t.length === w.length || !/[a-z0-9]/.test(t.charAt(w.length)));
  };
  return opensOn(n) || (first.length >= 3 && opensOn(first));
}

function firstSentence(text) {
  const m = str(text).match(/^[\s\S]*?[.!?](?=\s|$)/);
  return m ? m[0] : str(text);
}

function countOf(re, text) {
  return (str(text).match(new RegExp(re.source, re.flags.indexOf('g') === -1 ? re.flags + 'g' : re.flags)) || []).length;
}

// ---------------------------------------------------------------------------
// The rule checks. Each returns the tags it found; checkMessage runs them all.
// ---------------------------------------------------------------------------

// "Exactly one ask."
function askFlags(body, ask) {
  const flags = [];
  const q = countOf(/\?/, ask);
  if (!str(ask) || q === 0) flags.push('ask-none');
  if (q > 1 || REQUEST_IN_BODY.test(body)) flags.push('ask-multiple');
  if (ASK_SCHEDULING.test(ask)) flags.push('ask-scheduling');
  return flags;
}

// "The name appears at most once, in brackets." Stripping every bracketed
// segment leaves nothing that may still say the name.
function productFlags(text) {
  const flags = [];
  const name = new RegExp('\\b' + PRODUCT_NAME + '\\b', 'gi');
  const n = countOf(name, text);
  if (n > PRODUCT_NAME_MAX) flags.push('product-name-repeat');
  const unbracketed = str(text).replace(/\([^()]*\)/g, ' ');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(unbracketed)) flags.push('product-name-unbracketed');
  return flags;
}

// "The word 'AI' appears at most once ... Never 'AI-powered'."
function aiFlags(text) {
  const flags = [];
  if (countOf(/\bA\.?I\b\.?/, text) > AI_MAX) flags.push('ai-repeat');
  if (AI_POWERED.test(text)) flags.push('ai-powered');
  return flags;
}

function prospectSponsor(text) {
  return PROSPECT_SPONSOR.some(function (re) { return re.test(text); });
}

// Skill v3 section 3, Claims, forbidden.
function claimFlags(text, corpus) {
  const flags = [];
  if (GUARANTEE.test(text)) flags.push('claim-guarantee');
  if (unlicensedNumbers(text, corpus).length) flags.push('claim-number');
  if (VISITOR_ID.test(text)) flags.push('claim-visitor-id');
  const t = ' ' + fold(text) + ' ';
  if (NAMED_TOOLS.some(function (n) { return new RegExp('(^|[^a-z0-9])' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(t); })) {
    flags.push('claim-named-tool');
  }
  if (LANGUAGES.test(text)) flags.push('claim-language');
  if (CHATBOT.test(text)) flags.push('claim-chatbot');
  if (NOVA_BOOKS.test(text)) flags.push('claim-books');
  if (SOP_SOURCE.test(text)) flags.push('claim-sop');
  return flags;
}

// Skill v3 section 3, No repeats: "The description and the benefits must not
// repeat the same capability." Each description and benefit line names its
// capabilities (claims_library.capabilities, migration 013); two codes one
// message used that share one say the same thing twice. `capsOf(code)` returns
// a code's capabilities (none for an angle, proof or ask).
function repeatFlags(codes, capsOf) {
  const flags = [];
  const seen = {};
  let repeated = false;
  for (const code of codes || []) {
    for (const cap of capsOf(code) || []) {
      if (seen[cap] && seen[cap] !== code) repeated = true;
      seen[cap] = code;
    }
  }
  if (repeated) flags.push('claim-repeat');
  return flags;
}

// "Proof: one named live deployment, matched to the lead's geography."
function proofFlags(text, proofPool) {
  const flags = [];
  const pool = proofPool || [];
  const allowed = DEPLOYMENTS.filter(function (d) {
    return pool.some(function (p) { return fold(p.body).indexOf(fold(d)) !== -1; });
  });
  const both = pool.some(function (p) { return /\btwo CROs\b/i.test(p.body); });
  const named = DEPLOYMENTS.filter(function (d) { return fold(text).indexOf(fold(d)) !== -1; });
  if (named.some(function (d) { return allowed.indexOf(d) === -1; })) flags.push('proof-geo');
  const present = named.some(function (d) { return allowed.indexOf(d) !== -1; }) ||
    (both && /\btwo (?:CROs|CRO clients|clients)\b/i.test(text));
  if (!present) flags.push('proof-missing');
  return flags;
}

// The first sentence opens on the prospect fact. Section 9 Workflow 4:
// founder_name and city never open a message; a trial is never credited to
// their website.
function hookFlags(hook, src, titles) {
  const flags = [];
  if (startsWithName(hook, src.founder_name) || startsWithName(hook, src.city)) flags.push('hook-opener');
  const own = withoutTitles(hook, titles);
  const titlesNamed = (titles || []).filter(function (t) {
    return str(t) && hook.toLowerCase().indexOf(str(t).toLowerCase()) !== -1;
  }).length;
  const trialOnSite = SITE_CLAIM.test(own) && (titlesNamed > 0 || TRIAL_WORD.test(own));
  if (HOOK_SOURCE_OPENING.test(hook) || trialOnSite) flags.push('hook-source');
  return flags;
}

function linkFlags(text, week, approvedLink) {
  const flags = [];
  const urls = urlsIn(text);
  if (urls.length > MAX_URLS) flags.push('urls');
  if (urls.length && week <= LINK_FREE_WEEKS) flags.push('link-in-warmup');
  const approved = approvedLink ? urlsIn(approvedLink.body) : [];
  if (urls.some(function (u) { return approved.indexOf(u) === -1; })) flags.push('unapproved-link');
  if (urls.some(function (u) { return /linkedin\.com/i.test(u); })) flags.push('linkedin-link');
  if (urls.some(function (u) { return /\.pdf\b/i.test(u); })) flags.push('pdf-link');
  return flags;
}

function subjectFlags(subject, factCorpus, headcount, titles, absentAreas) {
  const flags = [];
  const chars = Array.from(subject).length;
  if (!subject || chars < SUBJECT_MIN_CHARS || chars > SUBJECT_MAX_CHARS) flags.push('subject');
  if (new RegExp('\\b' + PRODUCT_NAME + '\\b', 'i').test(subject)) flags.push('subject-product');
  if (/\bA\.?I\b/i.test(subject)) flags.push('subject-ai');
  const prefix = new RegExp('\\b(' + SUBJECT_REPLY_PREFIXES.join('|') + ')\\s*:', 'i');
  if (prefix.test(subject)) flags.push('subject-reply');
  // "No capitals": sentence case. A capitalised word after the first is allowed
  // only when the facts spell it that way (a trial code, a city) or it is an
  // acronym a CRO uses.
  const corpusWords = {};
  (factCorpus.match(/[\p{L}\p{N}-]+/gu) || []).forEach(function (t) { corpusWords[t] = true; });
  const tokens = subject.match(/[\p{L}\p{N}-]+/gu) || [];
  const capped = tokens.filter(function (t, i) {
    if (!/\p{Lu}/u.test(t)) return false;
    if (i === 0 && !/^\p{Lu}{2,}$/u.test(t)) return false;
    return !corpusWords[t] && SUBJECT_ACRONYMS.indexOf(t.toUpperCase()) === -1;
  });
  if (capped.length) flags.push('subject-caps');
  const corpus = factCorpus + (headcount ? ' ' + headcount : '');
  const bare = withoutTitles(subject, titles);
  if (digitTokens(bare).some(function (t) { return digitTokens(corpus).indexOf(t) === -1; }) ||
      absentAreasNamed(bare, absentAreas).length) {
    flags.push('subject-ungrounded');
  }
  return flags;
}

// Every rule that applies to a message body, either channel.
function checkMessage(m) {
  let flags = [];
  if (!str(m.body)) flags.push('empty');
  if (words(m.core) > BODY_CEILING) flags.push('long');
  if (bannedAdjectivesIn(m.core).length) flags.push('adjective');
  if (MERGE_TAG.test(m.core)) flags.push('merge-tag');
  flags = flags.concat(askFlags(m.body, m.ask));
  flags = flags.concat(productFlags(m.core));
  flags = flags.concat(aiFlags(m.core));
  if (prospectSponsor(m.core)) flags.push('prospect-sponsor');
  const own = withoutTitles(m.core, m.titles);
  flags = flags.concat(claimFlags(own, m.corpus));
  if (absentAreasNamed(own, m.absentAreas).length) flags.push('ungrounded-area');
  if (str(m.body)) flags = flags.concat(hookFlags(firstSentence(m.body), m.src, m.titles));
  flags = flags.concat(proofFlags(m.core, m.proofPool));
  return flags;
}

function unique(list) {
  return list.filter(function (v, i) { return list.indexOf(v) === i; });
}

// Word-set overlap, for attributing an ask the model did not code to the library
// line it paraphrased. Also used by the follow-ups (Workflow 6), which embed
// everything above "Node body" verbatim.
function wordSet(v) {
  const set = {};
  fold(v).replace(/[^a-z0-9]+/g, ' ').split(' ').filter(Boolean).forEach(function (w) { set[w] = true; });
  return set;
}
function jaccard(a, b) {
  const A = wordSet(a);
  const B = wordSet(b);
  const keys = unique(Object.keys(A).concat(Object.keys(B)));
  const both = keys.filter(function (k) { return A[k] && B[k]; }).length;
  return keys.length ? both / keys.length : 0;
}

// ---------------------------------------------------------------------------

// ===========================================================================
// The questions a reply may not answer -- shared by Build Reply and Assemble
// Reply (Section 9, Workflow 7). build_workflow.py prepends this file to both
// nodes, so the topic one node detects in the prospect's message is the same
// topic the other checks the draft against; two copies would drift and the
// drift would be invisible.
// ===========================================================================
//
// WHAT A REPLY MAY SAY is exactly what a first touch may say: the confirmed
// `claims_library` lines, and the facts in the lead's own enrichment record.
// Migration 013 narrowed every claim to what the Nova Agent Kit code actually
// does (`capabilities`), so "what the claims support" and "what the code
// supports" are the same set by construction, and a sentence outside it is an
// invention whether or not it happens to be true.
//
// A prospect's first reply, though, is usually a QUESTION, and the questions
// that come back are mostly about things no claim covers: what it costs, what
// it plugs into, which languages it speaks, where the data lives, how long it
// takes. The first touch never raised any of them, so there is nothing to
// widen -- which is precisely why a model will answer them from nowhere.
//
// So the answer is not "tag it afterwards", it is "do not answer it": the topic
// is detected in THEIR text before the model is called, the model is told to
// say we will confirm it, and the draft is flagged to the operator, who knows
// the answer and can put it in with EDIT. The five topics are the operator's
// list (2026-10-09).
//
// The patterns are deliberately broad. A false positive costs one hedged
// sentence and one line in the review email; a false negative is a made-up
// price or a made-up integration sent to a prospect over the operator's name.
const OPEN_TOPICS = [
  {
    topic: 'pricing',
    label: 'what it costs',
    re: /\b(?:pric(?:e|es|ing)|cost|costs|costly|how much|fee|fees|budget|quote|quotation|licen[cs]\w*|subscription|per (?:month|year|seat|user)|monthly|annual(?:ly)?|retainer|discount|invoice|payment terms)\b/i,
  },
  {
    topic: 'integrations',
    label: 'what it connects to',
    re: /\b(?:integrat\w*|API|APIs|webhook\w*|CRM|salesforce|hubspot|zapier|SSO|single sign-?on|LDAP|CTMS|eTMV|eTMF|EDC|SharePoint|Teams|Slack|calendar|google workspace|office ?365|plug(?:s|ged)? into|connect(?:s|ed|ion|ions)? (?:to|with))\b/i,
  },
  {
    topic: 'languages',
    label: 'which languages it speaks',
    re: /\b(?:language|languages|multi-?lingual|translat\w*|english|turkish|spanish|arabic|german|french|portuguese|polish|romanian|hungarian|czech|hindi|urdu|mandarin|japanese)\b/i,
  },
  {
    topic: 'security',
    label: 'security, hosting and data protection',
    re: /\b(?:secur\w*|GDPR|KVKK|HIPAA|GxP|21 CFR|part 11|data protection|privacy|confidential\w*|NDA|DPA|encrypt\w*|anonymi[sz]\w*|pseudonymi[sz]\w*|hosted?|hosting|on-?prem\w*|server location|where (?:is|are) (?:the )?data|data (?:residency|centre|center|retention|storage)|SOC ?2|ISO ?27001|penetration test|audit trail|validat\w*)\b/i,
  },
  {
    topic: 'timelines',
    label: 'how long it takes and when it can start',
    re: /\b(?:timeline|time-?line|how long|lead ?time|turn ?around|go[- ]live|deadline|availabilit\w*|when (?:can|could|would|will)|start date|roll ?out|implementation (?:time|period)|SLA|uptime|support hours|response time|maintenance)\b/i,
  },
];

// A sentence that says we will come back with the answer, rather than giving
// one. Assemble Reply requires one of these for every topic the prospect
// raised: without it, a paragraph that mentions pricing is answering about
// pricing.
const DEFERRAL_RE = /\b(?:I(?:'| wi)?ll (?:confirm|check|find out|come back|get back|send you the detail)|let me (?:confirm|check|find out)|I (?:do not|don't) want to guess|rather than guess|confirm (?:that|this|these|the detail)|get back to you (?:on|with|about)|come back to you (?:on|with|about)|check (?:that|this) (?:and|then|with)|I will ask)\b/i;

// Which of the five the prospect actually raised, in the order above.
function topicsIn(text) {
  const t = String(text === null || text === undefined ? '' : text);
  return OPEN_TOPICS.filter(function (o) { return o.re.test(t); }).map(function (o) { return o.topic; });
}

function topicLabel(topic) {
  const hit = OPEN_TOPICS.filter(function (o) { return o.topic === topic; })[0];
  return hit ? hit.label : topic;
}

function topicRe(topic) {
  const hit = OPEN_TOPICS.filter(function (o) { return o.topic === topic; })[0];
  return hit ? hit.re : null;
}

function deferralIn(text) {
  return DEFERRAL_RE.test(String(text === null || text === undefined ? '' : text));
}

// ===========================================================================
// Assemble Reply -- n8n Code node (Run Once for Each Item).
//
// build_workflow.py ships this node as three parts: drafting's code_assemble.js
// above its "Node body" marker (verbatim -- the first touch's own claim rules),
// then code_reply_topics.js (the five questions a reply may not answer), then
// this file. So a reply is judged by askFlags, claimFlags, productFlags,
// aiFlags, proofFlags, linkFlags and the rest exactly as a first touch and a
// follow-up are, rather than by a copy of them that could drift.
//
// What this adds is the reply's own rules:
//
//   length    body plus next step, 40-120 words (`short`, `long`)
//   proof     the "two CROs" wording is never reused and Vertex Clinical
//             Research is never called a CRO -- it is a clinical research
//             centre (operator instruction, 2026-10-09): `proof-refused`
//   deferral  every topic they raised that no claim and no record fact can
//             settle must be named in `deferred` (`deferral-missing`) and must
//             be answered with "we will confirm", not with an answer
//             (`answered-open`)
//   frame     greeting, signature and their quoted message are appended here,
//             never generated
//
// NO OPT-OUT LINE, and that is deliberate. Section 5's "reply 'no' and I won't
// follow up" is the opt-out mechanism for a message the prospect did not ask
// for. This is an answer to a message they sent us, inside their own thread,
// and the opt-out sentence in it would read as a form letter; replying is
// already the trivial opt-out the GDPR/KVKK position requires. The send path
// checks a reply for the SIGNATURE rather than for the opt-out tail
// (code_reply_decide.js), and nothing else about the frame changes.
//
// A violation tags `variant` rather than discarding the draft, as everywhere
// else in Workflow 4: the operator reads the tag next to the text in the
// review email. A failed call writes nothing and the reply is queued again on
// the next run (no fallback model -- skill section 6).
// ===========================================================================

const REPLY_MIN_WORDS = 40;
const REPLY_MAX_WORDS = 120;
const SIGNATURE = "Abdullah Amir\nFounder, Amitrix Labs\n+923178485713";

// Operator instruction, 2026-10-09, checked on the TEXT and not on a code, so a
// reworded library row cannot escape it. The same list Build Reply filters the
// offered proof with -- a reply may still name a deployment the library offers
// for this country, just never in these words.
const REPLY_PROOF_REFUSED = [/\btwo CROs?\b/i, /\bVertex\b[^.]{0,40}\bCRO\b/i];

const src = $('Build Reply').item.json;
const resp = $input.item.json;

function failed(detail) {
  return {
    json: {
      lead_id: src.lead_id,
      inbound_message_id: src.inbound_message_id,
      write: false,
      skip_reason: 'Claude reply call did not answer usably: ' + detail,
      usage: resp && resp.usage ? resp.usage : null,
    },
  };
}

if (!resp || typeof resp !== 'object') return failed('no response item');
if (resp.error) {
  const e = resp.error;
  return failed((typeof e === 'string' ? e : JSON.stringify(e)).slice(0, 300));
}
if (resp.stop_reason !== 'end_turn') {
  const why = resp.stop_details && resp.stop_details.category ? ' (' + resp.stop_details.category + ')' : '';
  return failed('stop_reason ' + JSON.stringify(resp.stop_reason) + why);
}
const text = (Array.isArray(resp.content) ? resp.content : [])
  .filter(function (b) { return b && b.type === 'text'; })
  .map(function (b) { return b.text; })
  .join('');
let parsed = null;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = null;
}
const REPLY_FIELDS = ['body', 'ask', 'flag'];
const REPLY_LISTS = ['claims', 'deferred'];
if (!parsed || typeof parsed !== 'object' ||
    REPLY_FIELDS.some(function (f) { return typeof parsed[f] !== 'string'; }) ||
    REPLY_LISTS.some(function (f) { return !Array.isArray(parsed[f]); })) {
  return failed('response text was not the reply schema: ' + text.slice(0, 200));
}

// --- the claims this reply used ----------------------------------------------

const pools = src.library_pools || {};
const offered = {};
SLOT_ORDER.forEach(function (slot) {
  (pools[slot] || []).forEach(function (l) {
    offered[l.code] = { slot: slot, confirmed: l.confirmed, capabilities: l.capabilities || [] };
  });
});
const approvedLink = (pools.link || [])[0] || null;

const body = cleanText(parsed.body, src.greeting);
const ask = cleanText(parsed.ask, src.greeting);
const core = [body, ask].filter(Boolean).join('\n\n');

// Reported codes against what this reply was offered. As in Workflow 4 and the
// follow-ups, an ask or a proof the model left uncoded is attributed from the
// text: the model is never trusted to copy an identifier.
const reported = unique(parsed.claims.map(str).filter(Boolean));
const unknown = reported.filter(function (c) { return !offered[c]; });
let used = reported.filter(function (c) { return offered[c]; });
if (!used.some(function (c) { return offered[c].slot === 'ask'; })) {
  let best = null;
  (pools.ask || []).forEach(function (l) {
    const j = jaccard(ask, l.body);
    if (j >= 0.5 && (!best || j > best.j)) best = { code: l.code, j: j };
  });
  if (best) used.push(best.code);
}
if (!used.some(function (c) { return offered[c].slot === 'proof'; })) {
  (pools.proof || []).forEach(function (l) {
    const names = DEPLOYMENTS.filter(function (d) { return fold(l.body).indexOf(fold(d)) !== -1; });
    if (names.some(function (d) { return fold(core).indexOf(fold(d)) !== -1; }) && used.indexOf(l.code) === -1) {
      used.push(l.code);
    }
  });
}
used = unique(used).sort(function (a, b) {
  return SLOT_ORDER.indexOf(offered[a].slot) - SLOT_ORDER.indexOf(offered[b].slot);
});

const deferred = unique(parsed.deferred.map(str).filter(Boolean).map(function (d) { return d.toLowerCase(); }));
const openTopics = Array.isArray(src.open_topics) ? src.open_topics : [];
const flag = str(parsed.flag);

// --- the checks ---------------------------------------------------------------

function replyFlags() {
  let flags = [];
  const wc = words(core);
  if (!body) flags.push('empty');
  if (wc > REPLY_MAX_WORDS) flags.push('long');
  if (wc && wc < REPLY_MIN_WORDS) flags.push('short');
  if (bannedAdjectivesIn(core).length) flags.push('adjective');
  if (MERGE_TAG.test(core)) flags.push('merge-tag');
  flags = flags.concat(askFlags(body, ask));
  flags = flags.concat(productFlags(core));
  flags = flags.concat(aiFlags(core));
  if (prospectSponsor(core)) flags.push('prospect-sponsor');
  flags = flags.concat(claimFlags(core, src.corpus));
  if (absentAreasNamed(core, src.absent_areas).length) flags.push('ungrounded-area');
  // A reply need not name a deployment at all; one it DOES name must be this
  // lead's, so only proof-geo applies (the follow-ups make the same cut).
  flags = flags.concat(proofFlags(core, pools.proof).filter(function (f) { return f === 'proof-geo'; }));
  if (REPLY_PROOF_REFUSED.some(function (re) { return re.test(core); })) flags.push('proof-refused');
  // The link policy, with the warm-up week deliberately out of range: a reply
  // is not cold outreach, so the week-1-2 link ban does not apply to it. What
  // does apply is the cap -- at most one URL, and only the library's own
  // confirmed `link` line (none is confirmed today, so any URL is tagged).
  flags = flags.concat(linkFlags(core, LINK_FREE_WEEKS + 1, approvedLink));
  if (unknown.length || !reported.length) flags.push('claim-code');
  flags = flags.concat(repeatFlags(used, function (c) { return offered[c].capabilities; }));
  if (used.some(function (c) { return !offered[c].confirmed; })) flags.push('unconfirmed-claim');
  // Every topic they raised has to be named as deferred...
  if (openTopics.some(function (t) { return deferred.indexOf(t) === -1; })) flags.push('deferral-missing');
  // ... and deferred means "we will confirm", not an answer. A reply that talks
  // about one of those topics with no such sentence anywhere has answered it.
  if (openTopics.length && !deferralIn(core)) flags.push('answered-open');
  else if (openTopics.some(function (t) {
    const re = topicRe(t);
    return re && re.test(core) && !deferralIn(core);
  })) {
    flags.push('answered-open');
  }
  return unique(flags);
}

const flags = replyFlags();

// --- the sendable text --------------------------------------------------------
//
// Greeting / reply / next step / signature, then THEIR message quoted. An EDIT
// from the operator replaces only the middle and keeps this frame
// (code_operator_command.js's framedEdit), which is why the signature is the
// marker it splits on.

const theirs = String(src.their_text || '').replace(/\r\n?/g, '\n').trim();
const when = new Date(src.received_at);
const whenText = isNaN(when.getTime()) ? 'earlier' : when.toUTCString().slice(0, 16);
const quoted = theirs.split('\n').map(function (ln) { return ln ? '> ' + ln : '>'; }).join('\n');
const full = [
  src.greeting,
  '',
  core,
  '',
  SIGNATURE,
  '',
  'On ' + whenText + ', ' + str(src.quote_attribution) + ' wrote:',
  quoted,
].join('\n');

const variant = 'reply/' + used.join('.') + (flags.length ? '+' + flags.join(',') : '');

return {
  json: {
    lead_id: src.lead_id,
    inbound_message_id: src.inbound_message_id,
    write: true,
    flags: flags,
    words: words(core),
    claims: used,
    deferred: deferred,
    open_topics: openTopics,
    flag: flag,
    model: resp.model,
    usage: resp.usage || null,
    composition: parsed,
    // What the review email shows the operator, alongside the draft itself.
    review: {
      company_name: src.company_name,
      domain: src.domain,
      country: src.country,
      from_addr: src.from_addr,
      their_subject: src.their_subject,
      their_text: theirs,
      received_at: src.received_at,
      deferred: deferred.map(function (t) { return topicLabel(t); }),
      flag: flag,
      flags: flags,
      words: words(core),
      claims: used,
    },
    payload: {
      lead_id: src.lead_id,
      inbound_message_id: src.inbound_message_id,
      draft: {
        channel: 'email',
        variant: variant,
        subject: src.subject,
        body: full,
      },
    },
  },
};

// Build Review Email -- n8n Code node (Run Once for Each Item).
//
// Section 9, Workflow 7: "Save it as a pending draft and email me the reply, the
// proposal and a one-time code." This is that email.
//
// Built from the row "Write Reply Draft & Issue Code" returned, so everything in
// it is what the database actually holds: the draft is `pending`, the code is
// the one `reply_approvals` stores, and the expiry is the one its CHECK bounded
// to 48 hours. The operator's address comes on the same row, read at runtime
// from `settings` (migration 008), so no address is baked into this workflow.
//
// It shows four things, in this order:
//   1. WHAT THEY WROTE -- the text above the quoted thread, verbatim.
//   2. THE PROPOSED REPLY -- the exact bytes that would be sent, frame and all,
//      so there is nothing to imagine.
//   3. WHAT IT DOES NOT ANSWER -- every topic they raised that no confirmed
//      claim and no record fact can settle (pricing, integrations, languages,
//      security, timelines), plus whatever the drafter flagged. This is the half
//      of the email the operator is the only one who can act on.
//   4. THE THREE COMMANDS, each with the code, and what each one does.
//
// Like a reply notification and the daily digest it goes only to the operator's
// own inbox, so it uses no warm-up slot.

// One bare address -- the build's rule, and migration 008's CHECK.
const REVIEW_ADDRESS = /^[^\s@<>(),;:"']+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$/;

function vStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function vList(v) {
  return Array.isArray(v) ? v.map(vStr).filter(Boolean) : [];
}

function reviewAddress(r) {
  const a = vStr(r.operator_email).toLowerCase();
  return REVIEW_ADDRESS.test(a) ? a : '';
}

function reviewEmail(r) {
  const to = reviewAddress(r);
  const v = (r.review && typeof r.review === 'object') ? r.review : {};
  const code = vStr(r.code);
  const who = vStr(v.company_name) || vStr(v.domain) || ('lead ' + vStr(r.lead_id));
  const flags = vList(v.flags);
  const deferred = vList(v.deferred);
  const flag = vStr(v.flag);

  const lines = [
    who + ' (' + vStr(v.domain) + ', ' + vStr(v.country) + ') replied, and this is the answer I drafted.',
    'Nothing is sent until you say so.',
    '',
    'Draft:     ' + vStr(r.draft_id) + ' (pending, channel email, variant reply)',
    'Lead:      ' + vStr(r.lead_id),
    'Reply to:  ' + vStr(v.from_addr) + '   (the address that wrote, not the contact on file)',
    'Received:  ' + vStr(v.received_at),
    'Length:    ' + vStr(v.words) + ' words' + (v.claims && v.claims.length ? ', claims ' + vList(v.claims).join('.') : ''),
    'Code:      ' + code + '   (expires ' + vStr(r.expires_at) + ', works once)',
    '',
    '================================================================',
    'WHAT THEY WROTE',
    '================================================================',
    '',
    vStr(v.their_text) || '(no text above the quoted thread)',
    '',
    '================================================================',
    'THE PROPOSED REPLY -- exactly what would be sent',
    '================================================================',
    '',
    'Subject: ' + vStr(r.subject),
    '',
    vStr(r.body),
    '',
    '================================================================',
    'WHAT IT DOES NOT ANSWER, AND WHAT TO LOOK AT',
    '================================================================',
    '',
  ];

  if (deferred.length) {
    lines.push('They asked about this, and nothing we have confirmed covers it, so the draft says');
    lines.push('we will confirm and comes to you instead:');
    deferred.forEach(function (d) { lines.push('  - ' + d); });
    lines.push('');
    lines.push('You know these answers. EDIT is how they get in.');
    lines.push('');
  } else {
    lines.push('Nothing they asked falls outside the confirmed claims and their own record.');
    lines.push('');
  }
  if (flag) {
    lines.push('Flagged by the drafter: ' + flag);
    lines.push('');
  }
  if (flags.length) {
    lines.push('Rule tags on this draft (Workflow 4\'s own rules, run over the reply):');
    flags.forEach(function (f) { lines.push('  - ' + f); });
    lines.push('');
  } else {
    lines.push('No rule tags: it passed every check Workflow 4 runs on a first touch.');
    lines.push('');
  }

  lines.push('================================================================');
  lines.push('WHAT TO SEND BACK');
  lines.push('================================================================');
  lines.push('');
  lines.push('Reply to this email with one of these as the first line:');
  lines.push('');
  lines.push('  APPROVE ' + code);
  lines.push('      Sends it as it stands, on the next send tick. A reply skips the warm-up');
  lines.push('      ceiling and business hours; it never skips the blocklist.');
  lines.push('');
  lines.push('  REJECT ' + code);
  lines.push('      Sends nothing. Their message stays on the lead.');
  lines.push('');
  lines.push('  EDIT ' + code);
  lines.push('      ...then your own text, on the rest of that line and the lines after it.');
  lines.push('      Your words replace the draft\'s, under the same greeting and signature,');
  lines.push('      and it is approved. This is the one to use for the questions above.');
  lines.push('');
  lines.push('The code works once and expires ' + vStr(r.expires_at) + '. Only this address can use');
  lines.push('it, and only with SPF and DKIM passing -- anything else is logged and ignored.');
  lines.push('I will remind you in 4 hours if I have not heard back.');
  lines.push('');
  lines.push('-- Nova Scout (Workflow 7, Reply Assistant). Sent only to this address; it uses no');
  lines.push('   warm-up slot.');

  return {
    notify: Boolean(r.written) && to !== '' && code !== '',
    notify_to: to,
    subject: ('[Nova Scout] REPLY DRAFTED for ' + who + ' -- ' + code).slice(0, 200),
    text: lines.join('\n'),
    record: {
      code: code,
      draft_id: r.draft_id,
    },
  };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

return { json: reviewEmail($input.item.json) };

// Build Reminder -- n8n Code node (Run Once for Each Item).
//
// Section 9, Workflow 7: "Remind me after 4 hours." A one-time code sits in the
// mailbox for at most 48 hours (migration 017's CHECK) and then stops working,
// so a drafted reply nobody answered is a prospect left waiting and a code that
// quietly dies. This nudges, and keeps nudging every REMIND_HOURS while the
// code is still open -- the same shape as the IMAP health check's reminder,
// which repeats every 6 hours while a problem lasts.
//
// "Find Due Reminders" decides what is due, in SQL, from
// `coalesce(reminded_at, issued_at)` -- so the first reminder lands 4 hours
// after the code was issued and each later one 4 hours after the last. The last
// one before the window closes says how little time is left.
//
// It covers BOTH kinds of code, because both are the operator waiting on the
// same decision: a `reply` drafted for a prospect who wrote to us, and an
// `email-hold` -- a first touch or follow-up the claim check held after its
// repairs, which the daily digest listed with a code of its own.
//
// Recorded only once SMTP accepted it ("Record Reminder"), so a reminder that
// could not go out is sent on the next tick instead of being lost.

const REMIND_ADDRESS = /^[^\s@<>(),;:"']+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$/;

const KIND_LABEL = {
  'reply': 'a reply to a prospect who wrote to us',
  'email-hold': 'an email the claim check held for a person',
};

function mStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function remindAddress(r) {
  const a = mStr(r.operator_email).toLowerCase();
  return REMIND_ADDRESS.test(a) ? a : '';
}

function hoursBetween(from, to) {
  const a = new Date(from).getTime();
  const b = new Date(to).getTime();
  if (isNaN(a) || isNaN(b)) return null;
  return Math.round((b - a) / 3600000);
}

function reminder(r) {
  const to = remindAddress(r);
  const code = mStr(r.code);
  const who = mStr(r.company_name) || mStr(r.domain) || ('lead ' + mStr(r.lead_id));
  const open = hoursBetween(r.issued_at, r.now);
  const left = hoursBetween(r.now, r.expires_at);
  const kind = mStr(r.kind);

  const lines = [
    'Still waiting on you: ' + (KIND_LABEL[kind] || kind) + '.',
    '',
    'Company:   ' + who + ' (' + mStr(r.domain) + ', ' + mStr(r.country) + ')',
    'Draft:     ' + mStr(r.draft_id) + ' (' + mStr(r.channel) + ', ' + mStr(r.variant) + ', still pending)',
    'Code:      ' + code,
    'Issued:    ' + mStr(r.issued_at) + (open === null ? '' : '  (' + open + ' h ago)'),
    'Expires:   ' + mStr(r.expires_at) +
      (left === null ? '' : (left <= 0 ? '  (expired)' : '  (' + left + ' h left)')),
    '',
  ];

  if (kind === 'reply') {
    lines.push('WHAT THEY WROTE');
    lines.push('');
    lines.push(mStr(r.their_text) || '(no text above the quoted thread)');
    lines.push('');
  } else if (mStr(r.hold_reason)) {
    lines.push('Why it was held:');
    lines.push('  ' + mStr(r.hold_reason));
    lines.push('');
  }

  lines.push('THE DRAFT');
  lines.push('');
  if (mStr(r.subject)) lines.push('Subject: ' + mStr(r.subject));
  lines.push('');
  lines.push(mStr(r.body));
  lines.push('');
  lines.push('Reply with one of these as the first line:');
  lines.push('');
  lines.push('  APPROVE ' + code);
  lines.push('  REJECT ' + code);
  lines.push('  EDIT ' + code + '   ...then your own text');
  lines.push('');
  lines.push('When the code expires nothing is sent and the draft stays pending; the next');
  lines.push('reminder carries a fresh code.');
  lines.push('');
  lines.push('-- Nova Scout (Workflow 7). Sent only to this address; it uses no warm-up slot.');

  return {
    notify: to !== '' && code !== '',
    notify_to: to,
    subject: ('[Nova Scout] still waiting: ' + who + ' -- ' + code).slice(0, 200),
    text: lines.join('\n'),
    record: { code: code },
  };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

return { json: reminder($input.item.json) };
